  async initiate(params: InitiateParams, credentials: Credentials, _ctx?: GatewayContext): Promise<InitiateResult> {
    const integrationKey = String(credentials["integration_key"] ?? '');
    const endpoint = `${String('')}/ws/request`;
    const payload = { ["integration_key"]: integrationKey, ["operation"]: "request", ["payment"]: { ["amount"]: Number((params.amount ?? '')), ["currency_code"]: String((params.currency ?? '')).toUpperCase(), ["merchant_payment_code"]: (params.trx_id ?? ''), ["name"]: "Customer Name", ["email"]: "customer@ownpay.test", ["payment_type_code"]: "_all", ["back_url"]: (params.redirect_url ?? '') } };
    const res = await gwJson({
      url: endpoint,
      method: 'POST',
      headers: { ["Content-Type"]: "application/json", ["User-Agent"]: "OwnPay Gateway Client/1.0.0" },
      body: JSON.stringify(payload),
      timeoutMs: 15000,
    });
    if (res.status !== 200) throw new Error(`${SLUG}: HTTP ${res.status} ${res.text}`);
    if (res.data === null) throw new Error(`${SLUG}: invalid response`);
    const d = res.data as Record<string, unknown>;
    const paymentData = ((d) as Record<string, unknown>)["payment"] ?? {};
    return {
          redirect_url: (String(((paymentData) as Record<string, unknown>)["redirect_url"] ?? '') || undefined) as string | undefined,
          session_id: (String(((paymentData) as Record<string, unknown>)["hash"] ?? '') || undefined) as string | undefined,
        };
  }

  async verify(callbackData: Record<string, unknown>, credentials: Credentials, _ctx?: GatewayContext): Promise<VerifyResult> {
    const cb = callbackData as Record<string, unknown>;
    if (String(cb["hash"] ?? '') === '') {
      return { success: false, gateway_trx_id: '', amount: null, status: 'failed' as const };
    }
    const integrationKey = String(credentials["integration_key"] ?? '');
    const endpoint = `${String('')}/ws/query`;
    const payload: Record<string, unknown> = { ["integration_key"]: integrationKey, ["hash"]: cb["hash"] ?? cb["gateway_trx_id"] };
    const res = await gwJson({
      url: endpoint,
      method: 'POST',
      headers: { ["User-Agent"]: "OwnPay Gateway Client/1.0.0" },
      body: JSON.stringify(payload),
      timeoutMs: 10000,
    });
    if (res.data === null) {
          return { success: false, gateway_trx_id: '', amount: null, status: 'failed' as const };
        }
    const d = res.data as Record<string, unknown>;
    const paymentData = ((d) as Record<string, unknown>)["payment"] ?? {};
    const ok = ["PE", "CO"].includes(String(((paymentData) as Record<string, unknown>)["status"]));
    return {
          success: ok,
          gateway_trx_id: '',
          amount: null,
          status: (ok ? 'completed' : 'failed') as VerifyResult['status'],
        };
  }

